const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometry: 50km radius around (40.923221, 104.238631)
  const lon = 104.238631;
  const lat = 40.923221;
  const point = ee.Geometry.Point([lon, lat]);
  const geom = point.buffer(50000); // 50km radius

  // Load MERRA-2 PM2.5 data
  const merra2 = ee.ImageCollection('MERRA2/MONTHLY');

  // Filter for February 2019
  const feb2019 = merra2
    .filter(ee.Filter.calendarRange(2019, 2019, 'year'))
    .filter(ee.Filter.calendarRange(2, 2, 'month'));

  // Filter for February 2020
  const feb2020 = merra2
    .filter(ee.Filter.calendarRange(2020, 2020, 'year'))
    .filter(ee.Filter.calendarRange(2, 2, 'month'));

  const size2019 = feb2019.size().getInfo();
  const size2020 = feb2020.size().getInfo();

  console.log(`Feb 2019 Images: ${size2019}`);
  console.log(`Feb 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log('No data found for one or both months.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Mean composite for each period
  const img2019 = feb2019.mean();
  const img2020 = feb2020.mean();

  // Select PM2.5 band
  const pm25_2019 = img2019.select('PM25');
  const pm25_2020 = img2020.select('PM25');

  // Calculate mean and pixel count for Feb 2019
  const stats2019 = pm25_2019.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9,
  });

  const mean2019 = stats2019.get('PM25_mean').getInfo();
  const count2019 = stats2019.get('PM25_count').getInfo();

  // Calculate mean and pixel count for Feb 2020
  const stats2020 = pm25_2020.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9,
  });

  const mean2020 = stats2020.get('PM25_mean').getInfo();
  const count2020 = stats2020.get('PM25_count').getInfo();

  console.log(`Feb 2019: Mean=${mean2019}, Pixels=${count2019}`);
  console.log(`Feb 2020: Mean=${mean2020}, Pixels=${count2020}`);

  // Validate data
  if (count2019 === 0 || count2020 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2019 === null || mean2020 === null || isNaN(mean2019) || isNaN(mean2020)) {
    console.log('Calculation resulted in invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare PM2.5 levels
  console.log(`Comparison: Feb2020 (${mean2020.toFixed(2)}) vs Feb2019 (${mean2019.toFixed(2)})`);

  if (mean2020 > mean2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
